<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cube </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GameObject.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CreatePrimitive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(PrimitiveType.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Cube</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
